package license

// PublicKeyHex is the hex-encoded Ed25519 public key used to verify license signatures.
// Generated by: vigo-license-manager keys inject
// PublicKeyHex may be overridden by setPublicKeyForTest during tests.
var PublicKeyHex = "59e96353a8034f5e179f231a8a8ddde0cc7d8959c84573d2e6035ab82cc7b5d6"

// setPublicKeyForTest replaces the public key and returns a restore function.
func setPublicKeyForTest(hex string) func() {
	old := PublicKeyHex
	PublicKeyHex = hex
	return func() { PublicKeyHex = old }
}
